#include <iostream>
#include <vector>
#include <string>

using namespace std;

/**
 * 題目 10432: Mine Sweeper
 * 模擬踩地雷：
 * 給定地雷分布圖與玩家的點擊位置圖。
 * 規則：
 * 1. 如果玩家點擊到地雷 ('x' 對應 '*')，則顯示所有地雷。
 * 2. 如果玩家點擊的是安全區，顯示周圍地雷數量。
 * 3. 未被點擊的安全區顯示 '.'。
 */

int main() {
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        cin >> n;
        vector<string> mines(n), played(n);
        for (int i = 0; i < n; ++i) cin >> mines[i];
        for (int i = 0; i < n; ++i) cin >> played[i];

        // 檢查是否踩到地雷
        bool mineTouched = false;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (played[i][j] == 'x' && mines[i][j] == '*') {
                    mineTouched = true;
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (mineTouched && mines[i][j] == '*') {
                    cout << '*';
                } else if (played[i][j] == 'x') {
                    int count = 0;
                    for (int di = -1; di <= 1; ++di) {
                        for (int dj = -1; dj <= 1; ++dj) {
                            int ni = i + di, nj = j + dj;
                            if (ni >= 0 && ni < n && nj >= 0 && nj < n && mines[ni][nj] == '*') {
                                count++;
                            }
                        }
                    }
                    cout << count;
                } else {
                    cout << '.';
                }
            }
            cout << endl;
        }
        if (T > 0) cout << endl;
    }
    return 0;
}
